:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #e94560;
  --text: #eaeaea;
  --accent: #0f3460;
  --food: #f5c542;
  --snake: #4ecca3;
  --snake-head: #3aa87d;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-container {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  max-width: 480px;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: 1px;
}

.score {
  font-size: 1.125rem;
  font-weight: 600;
  background: var(--accent);
  padding: 6px 14px;
  border-radius: 8px;
  white-space: nowrap;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 8px;
  overflow: hidden;
  background: #0d1b2a;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(13, 27, 42, 0.92);
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 24px;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
}

.overlay h2 {
  font-size: 1.5rem;
  color: var(--primary);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.5;
  color: var(--text);
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  background: var(--primary);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  min-width: 120px;
}

.btn:hover {
  background: #d63852;
}

.btn:focus-visible {
  outline: 3px solid var(--food);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
  background: #c02e46;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.controls .btn {
  flex: 1;
  max-width: 160px;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .score {
    font-size: 1rem;
    padding: 4px 10px;
  }
  .overlay h2 {
    font-size: 1.25rem;
  }
  .overlay p {
    font-size: 0.9375rem;
  }
  .btn {
    padding: 10px 16px;
    min-width: 100px;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const overlayBtn = document.getElementById('overlayBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID = 20;
  const CELL = canvas.width / GRID;

  let snake, food, direction, nextDirection, score, gameState, gameLoop;

  function init() {
    snake = [{ x: 10, y: 10 }];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
    score = 0;
    gameState = 'paused';
    scoreEl.textContent = 'Score: 0';
    placeFood();
    draw();
    updateUI();
  }

  function placeFood() {
    let pos;
    do {
      pos = {
        x: Math.floor(Math.random() * GRID),
        y: Math.floor(Math.random() * GRID)
      };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function draw() {
    ctx.fillStyle = '#0d1b2a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#f5c542';
    ctx.fillRect(food.x * CELL, food.y * CELL, CELL, CELL);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#3aa87d' : '#4ecca3';
      ctx.fillRect(seg.x * CELL, seg.y * CELL, CELL, CELL);
    });
  }

  function updateUI() {
    if (gameState === 'paused') {
      pauseBtn.textContent = 'Resume';
      pauseBtn.setAttribute('aria-label', 'Resume game');
    } else {
      pauseBtn.textContent = 'Pause';
      pauseBtn.setAttribute('aria-label', 'Pause game');
    }

    if (gameState === 'gameover') {
      overlayTitle.textContent = 'Game Over';
      overlayText.innerHTML = 'Final Score: ' + score + '<br>Press Restart to play again.';
      overlayBtn.textContent = 'Play Again';
      overlay.classList.remove('hidden');
    } else if (gameState === 'paused' && score === 0 && snake.length === 1) {
      overlayTitle.textContent = 'How to Play';
      overlayText.innerHTML = 'Use arrow keys to move the snake.<br>Eat the food to grow and score points.<br>Don\'t hit the walls or yourself!';
      overlayBtn.textContent = 'Start Game';
      overlay.classList.remove('hidden');
    } else if (gameState === 'paused') {
      overlayTitle.textContent = 'Paused';
      overlayText.textContent = 'Press Resume or the button below to continue.';
      overlayBtn.textContent = 'Resume';
      overlay.classList.remove('hidden');
    } else {
      overlay.classList.add('hidden');
    }
  }

  function step() {
    if (gameState !== 'running') return;

    direction = nextDirection;
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
        snake.some(s => s.x === head.x && s.y === head.y)) {
      gameState = 'gameover';
      clearInterval(gameLoop);
      updateUI();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = 'Score: ' + score;
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function startLoop() {
    clearInterval(gameLoop);
    gameLoop = setInterval(step, 150);
  }

  function startGame() {
    gameState = 'running';
    updateUI();
    startLoop();
  }

  function togglePause() {
    if (gameState === 'running') {
      gameState = 'paused';
      clearInterval(gameLoop);
    } else if (gameState === 'paused') {
      gameState = 'running';
      startLoop();
    }
    updateUI();
  }

  function restartGame() {
    clearInterval(gameLoop);
    init();
  }

  document.addEventListener('keydown', (e) => {
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(key)) {
      e.preventDefault();
      if (gameState !== 'running') return;

      if (key === 'ArrowUp' && direction.y !== 1) nextDirection = { x: 0, y: -1 };
      else if (key === 'ArrowDown' && direction.y !== -1) nextDirection = { x: 0, y: 1 };
      else if (key === 'ArrowLeft' && direction.x !== 1) nextDirection = { x: -1, y: 0 };
      else if (key === 'ArrowRight' && direction.x !== -1) nextDirection = { x: 1, y: 0 };
    }

    if (key === 'p' || key === 'P') {
      if (gameState === 'running' || gameState === 'paused') togglePause();
    }

    if (key === 'r' || key === 'R') {
      restartGame();
    }
  });

  overlayBtn.addEventListener('click', () => {
    if (gameState === 'gameover') {
      restartGame();
      startGame();
    } else if (gameState === 'paused') {
      startGame();
    }
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restartGame);

  init();
})();
